const bankTexts = {"en": {"label": "MIDI OUT Bank", "short": "Six parallel MIDI lanes with CC locks, slides and Scramble. Hardware tested.", "desc": "Hardware-tested CC slides: hold SETTINGS and press a TRIG to toggle Slide on / Slide off. Mark the destination step: differing CC values glide from the preceding trig into that step over the whole gap, following tempo and lane speed. The source can be trigless. An ordinary intervening note stops the lookahead; different CC numbers are not interpolated. Slide steps double-blink like Model-TG; an empty step becomes a C5 note slide. MIDI note-off output stays ahead of CC ramps. CC slides are hardware tested by AveyCole. Hold a TRIG and turn an assigned gray knob to lock its CC value on that step. A LOCK badge appears. Step playback sends the saved CC number/value; the assigned base value returns on the next active note trig without a CC lock for that knob; rests and trigless steps do not restore it. FUNC + TRIG creates a parameter-only step without a MIDI note; its CC value holds until another CC change. SETTINGS returns to the same B-side lane. DATA cycles Note/Vel/Len with hardware-tested stock field highlighting. In B-side, SETTINGS + TRACK scrambles assigned CC values on the selected lane using its own persistent random seed; A-side SCRAMBLE is unchanged. SETTINGS assignment uses a silent draft while existing locks keep playing. Step/lane copy, paste and clear include these locks. CC assignments and CC locks are RAM-only and reset on project load/restart; Save Project does not save CC locks in this first test. MIDI notes, timing, older step locks and MIDI LFO saving are unchanged. Experimental gray-knob CC controls in MIDI B-side. Hold SETTINGS and turn a gray knob to select OFF or CC0-127. Common CC names appear in the stock-style window and long names scroll. Release SETTINGS, then turn the knob to send a value on the selected MIDI lane channel and port. Assignment itself sends nothing. Muted/disabled lanes send nothing; unassigned knobs retain their earlier behavior. A-side controls are unchanged. The first test keeps assignments in RAM only, so they reset after restart. Hardware-tested MIDI sequence saving and live recording remain included."}, "fr": {"label": "Banque MIDI OUT", "short": "Six voies MIDI parallèles avec locks CC, slides et Scramble. Testées sur matériel.", "desc": "Slides CC testés sur matériel : SETTINGS + TRIG bascule Slide on / Slide off. Marquez le pas cible : les valeurs CC différentes glissent depuis le trig précédent vers ce pas sur tout l’intervalle, au tempo et à la vitesse de la voie. La source peut être un trig de paramètres. Une note normale intermédiaire arrête la recherche ; deux numéros CC différents ne sont pas interpolés. Double clignotement comme Model-TG ; pas vide transformé en note C5 slide. Les Note Off gardent priorité sur les rampes CC. Slides CC testés sur matériel par AveyCole. TRIG maintenu + potard assigné verrouille son CC sur ce pas, badge LOCK. Lecture transmet numéro/valeur verrouillés ; la valeur de base revient au prochain trig de note actif sans lock CC pour ce potard ; repos et trigs de paramètres ne la restaurent pas. FUNC + TRIG crée un pas de paramètres sans note MIDI ; sa valeur CC reste jusqu’au prochain changement CC. SETTINGS revient à la même voie B. DATA sélectionne Note/Vel/Len avec surbrillance stock testée sur matériel. Côté B, SETTINGS + TRACK randomise les CC assignés de la voie sélectionnée avec une graine persistante dédiée ; SCRAMBLE A reste inchangé. L’assignation SETTINGS utilise un brouillon silencieux sans suspendre les locks joués. Copie/colle/clear des pas/voies incluent les CC. Assignations et locks CC en RAM seulement, remis à zéro au chargement/redémarrage ; Save Project ne les conserve pas encore. Notes, timing, locks précédents et sauvegarde LFO MIDI inchangés. Test CC des potards gris côté MIDI B. SETTINGS + potard choisit OFF ou CC0-127. Noms courants dans une fenêtre style stock, défilement des noms longs. Relâchez SETTINGS puis tournez pour transmettre sur canal et port de la voie MIDI sélectionnée. Assignation silencieuse, voie muette/désactivée silencieuse, potards OFF inchangés. Côté A inchangé. Ce premier test garde les assignations en RAM seulement, remises à zéro au redémarrage. Sauvegarde des séquences MIDI et live-rec testés sur matériel conservés."}};
const bankFeature = {
 "id": "midi-bank-bundle",
 "cat": "seq",
 "status": "experimental",
 "label": "MIDI OUT Bank",
 "desc": "Test de sauvegarde MIDI et restauration au démarrage. Save Project écrit et vérifie les séquences B. Démarrage ou chargement d’un autre projet sauvegardé restaure ses séquences en arrière-plan. Attendre avant édition ou sauvegarde. Si le slot ne peut pas être associé, B reste accessible en RAM seule et les sauvegardes disque sont bloquées. Pas d’autosave des éditions. Écriture vérifiée sur matériel ; restauration après extinction à tester. Fichiers séparés hors backups Elektron. Sélections existantes, Model-TG et potard SPEED LFO2 conservés. Live-rec B inclus : RECORD + PLAY, puis PLAY avec RECORD maintenu pour changer la quantification. Save conserve notes, vélocité, durées en pas et retards au 1/64 de pas. Lit MBK2/MBK3, écrit MBK4 ; les anciennes versions ne lisent pas MBK4. Intégration live-rec/sauvegarde à tester sur matériel.",
 "requires": "model-tg",
 "credit": {
  "kind": "based",
  "who": "TinyGregAudio",
  "repo": "TinyGregAudio/Model-TG"
 },
 "license": "LICENSE-Model-TG",
 "variants": [
  {
   "id": "midi-bank-bundle",
   "label": null
  }
 ],
 "excludes": []
};
for (const key of ["label", "short", "desc"]) Object.defineProperty(bankFeature, key, {
  get: () => (bankTexts[document.documentElement.lang] || bankTexts.en)[key], configurable: true
});
